insert into storage.buckets (id,name,public) values ('plutonium-public','plutonium-public',true),('plutonium-private','plutonium-private',false) on conflict (id) do nothing;
create policy plutonium_public_read on storage.objects for select using (bucket_id = 'plutonium-public');
create policy plutonium_public_auth_insert on storage.objects for insert to authenticated with check (bucket_id = 'plutonium-public' and (storage.foldername(name))[1] in ('branding','properties'));
create policy plutonium_private_own_read on storage.objects for select to authenticated using (bucket_id = 'plutonium-private' and (storage.foldername(name))[1] = 'users' and (storage.foldername(name))[2] = (select auth.uid()::text));
create policy plutonium_private_own_insert on storage.objects for insert to authenticated with check (bucket_id = 'plutonium-private' and (storage.foldername(name))[1] = 'users' and (storage.foldername(name))[2] = (select auth.uid()::text));
